Tool response:
Tool: create_new_protocol_version
Description: Creates a new draft version of a protocol template, copying all steps and branches 
from the latest published version. The new version will be marked as 'draft'.
Parameters:
    {
      "type": "object",
      "properties": {
        "template_id": {
          "type": "integer",
          "description": "Internal ID of the protocol template",
          "title": "Template Id"
        },
        "new_version": {
          "type": "string",
          "title": "New Version",
          "description": "The new version number (e.g., '2.2')"
        }
      },
      "required": [
        "template_id",
        "new_version"
      ]
    }

Tool response:
Tool: update_protocol_step
Description: Modifies properties of a protocol step, including enabling dual nurse verification.
Parameters:
    {
      "type": "object",
      "properties": {
        "version_id": {
          "type": "integer",
          "description": "Internal ID of the protocol version",
          "title": "Version Id"
        },
        "step_id": {
          "type": "integer",
          "description": "Internal ID of the protocol step",
          "title": "Step Id"
        },
        "requires_dual_nurse_verification": {
          "type": "boolean",
          "title": "Requires Dual Nurse Verification",
          "description": "Whether dual nurse verification is required for this step"
        }
      },
      "required": [
        "version_id",
        "step_id",
        "requires_dual_nurse_verification"
      ]
    }

Tool response:
Tool: add_conditional_branch
Description: Adds a new conditional branch to a protocol step.
Parameters:
    {
      "type": "object",
      "properties": {
        "version_id": {
          "type": "integer",
          "description": "Internal ID of the protocol version",
          "title": "Version Id"
        },
        "step_id": {
          "type": "integer",
          "title": "Step Id",
          "description": "Internal ID of the protocol step to which the branch applies"
        },
        "condition_expression": {
          "type": "string",
          "title": "Condition Expression",
          "description": "Expression defining when the branch should be taken (e.g., 'patient.age < 18')"
        },
        "target_step_id": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Target Step Id",
          "description": "Internal ID of the step to jump to if condition is met"
        },
        "branch_label": {
          "type": "string",
          "title": "Branch Label",
          "description": "Label describing the purpose of this branch"
        }
      },
      "required": [
        "version_id",
        "step_id",
        "condition_expression",
        "branch_label"
      ]
    }

Tool response:
Tool: publish_protocol_version
Description: Publishes the specified draft version of a protocol template.
Updates status to 'published', sets published_at, and archives previous published versions.
Parameters:
    {
      "type": "object",
      "properties": {
        "version_id": {
          "type": "integer",
          "description": "Internal ID of the protocol version to publish",
          "title": "Version Id"
        }
      },
      "required": [
        "version_id"
      ]
    }
